"""Validation rules migrated from legacy/account_rules.vrl."""

from decimal import Decimal
from typing import Any


def _value(record: dict, column: str) -> Any:
    value = record.get(column, "")
    return "" if value is None else value


def _length(value: Any) -> int:
    if value is None:
        return 0
    return len(str(value))


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    """Evaluate applicable account rules in legacy rule-file order."""
    del today  # Part of the fixed interface; unused by these rules.

    errors: list[dict] = []

    if event in ("INSERT", "UPDATE"):
        # ACC-001
        if not (_length(_value(record, "ACCT_NM")) >= 2):
            errors.append(
                {
                    "code": "E1001",
                    "message": "Account name too short",
                    "severity": "BLOCK",
                }
            )

        # ACC-002
        account_type = _value(record, "ACCT_TYP")
        if not (
            account_type == "C"
            or account_type == "P"
            or account_type == "R"
            or account_type == "X"
        ):
            errors.append(
                {
                    "code": "E1002",
                    "message": "Invalid account type",
                    "severity": "BLOCK",
                }
            )

        # ACC-003
        annual_revenue = _value(record, "ANN_REV")
        if not (_number(annual_revenue) >= Decimal("0")):
            errors.append(
                {
                    "code": "E1003",
                    "message": "Annual revenue negative",
                    "severity": "BLOCK",
                }
            )

    if event == "UPDATE":
        # ACC-004
        old_credit_hold = _value(old or {}, "CRED_HOLD")
        credit_hold = _value(record, "CRED_HOLD")
        credit_limit = _number(_value(record, "CRED_LIMIT"))
        if not (
            not (
                old_credit_hold == "Y"
                and credit_hold == "N"
                and credit_limit <= Decimal("0")
            )
        ):
            errors.append(
                {
                    "code": "E1004",
                    "message": "Cannot release credit hold with zero credit limit",
                    "severity": "BLOCK",
                }
            )

    if event in ("INSERT", "UPDATE"):
        # ACC-005
        if not (_length(_value(record, "REGION_CD")) == 3):
            errors.append(
                {
                    "code": "E1005",
                    "message": "Region code must be 3 chars",
                    "severity": "WARN",
                }
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether any collected validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
